  ('T000001', 'merged', 'Eden', 'jarvi', 'Vasseur', 'jarvi', 'Data Analyst', 'Deauville, France, Deauville, France', 'jarvi', 'https://www.linkedin.com/in/eden-vasseur-3600/', 'Non', 'Vantis', 'jarvi', 'Entretien', 'LINKEDIN', NULL, NULL, NULL),
  ('T000002', 'merged', 'Anaé', 'jarvi', 'Lemoine', 'jarvi', 'Data Analyst', 'Toulouse, France, France', 'jarvi', 'https://www.linkedin.com/in/anaé-lemoine-8450/', 'Non', 'Bluemont', 'jarvi', 'Entretien', 'LINKEDIN', NULL, NULL, NULL),
  ('T000003', 'jarvi_only', 'Lou', 'jarvi', 'Perrot', 'jarvi', 'Software Engineer', 'Paris, France, Paris, France', 'jarvi', 'https://www.linkedin.com/in/lou-perrot-282/', 'Non', 'Vantis', 'jarvi', 'Entretien', 'LINKEDIN', NULL, NULL, NULL),
